  $("c_host").value = f.ssh_host; $("c_user").value = f.ssh_user; $("c_key").value = f.ssh_key_path; $("c_entry").value = f.jaeger_entry;
  $("c_loki").value = f.loki_url; $("c_port").value = f.ssh_port; $("c_compose").value = f.ssh_compose_file; $("c_services").value = f.services;
  $("c_step").value = f.step_seconds; $("c_base").value = f.baseline_minutes;
  if (f.missing && f.missing.length) $("c_msg").textContent = "Still needed: " + f.missing.join(", ");
