  if (S.source !== "live") document.querySelector('#srcseg button[data-v="live"]').click(); else { resetLive(); load(); } };
$("c_save").onclick = async () => {
  $("c_msg").textContent = "Saving…";
  const body = { original_name: editing, mode: connMode, system_name: $("c_name").value, jaeger_url: $("c_jaeger").value, jaeger_entry: $("c_entry").value,
    prometheus_url: $("c_prom").value, loki_url: $("c_loki").value, ssh_host: $("c_host").value, ssh_user: $("c_user").value, ssh_port: +$("c_port").value || 22,
    ssh_key_path: $("c_key").value, ssh_compose_file: $("c_compose").value, services: $("c_services").value,
    step_seconds: +$("c_step").value || 15, baseline_minutes: +$("c_base").value || 10 };
  const r = await (await fetch("/api/projects", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })).json();
  if (r.error) { $("c_msg").textContent = r.error; return; }
  editing = r.name; await refreshProjects();
  $("c_msg").textContent = r.missing.length ? "Saved. Still needed: " + r.missing.join(", ") : "Saved. Testing…";
  const t = await (await fetch("/api/projects/" + encodeURIComponent(r.name) + "/test", { method: "POST" })).json();
  $("c_res").innerHTML = (t.results || []).map(x => `<div class="res"><span class="dot ${x.ok ? "ok-dot" : "bad-dot"}"></span><b>${x.source}</b><span class="muted">${x.detail}</span><span class="muted" style="margin-left:auto">${x.ms} ms</span></div>`).join("");
  if (t.results && t.results.length && t.results.every(x => x.ok)) { $("c_msg").textContent = "Connected."; document.querySelector('#srcseg button[data-v="live"]').click(); }
};
$("c_del").onclick = async () => { if (!confirm("Delete project '" + editing + "'?")) return;
  await fetch("/api/projects/" + encodeURIComponent(editing), { method: "DELETE" }); $("conn").style.display = "none"; await refreshProjects(); resetLive(); if (S.source === "live") load(); };

"""
